mapper.insert:
INSERT INTO sys_imp_tmp_batch (
    imp_id, biz_type, template_code, file_name, file_size, file_path
    , target_id, target_name, target_type, biz_mode, option_json, reason
    , total_count, pass_count, fail_count, chk_rslt, chk_dscr
    , save_rslt, save_dscr, imp_time, opter_id, opter_name, result_json
    , is_deleted, crte_time, updt_time
) VALUES (
    #{impId}, #{bizType}, #{templateCode}, #{fileName}, #{fileSize}, #{filePath}
    , #{targetId}, #{targetName}, #{targetType}, #{bizMode}, #{optionJson}, #{reason}
    , #{totalCount}, #{passCount}, #{failCount}, #{chkRslt}, #{chkDscr}
    , #{saveRslt}, #{saveDscr}, #{impTime}, #{opterId}, #{opterName}, #{resultJson}
    , #{isDeleted}, #{crteTime}, #{updtTime}
)

mapper.update:
UPDATE sys_imp_tmp_batch
SET pass_count = #{passCount}
  , fail_count = #{failCount}
  , chk_rslt = #{chkRslt}
  , chk_dscr = #{chkDscr}
  , result_json = #{resultJson}
  , updt_time = #{updtTime}
WHERE imp_id = #{impId}
  AND is_deleted = 0

UPDATE sys_imp_tmp_batch
SET save_rslt = #{saveRslt}
  , save_dscr = #{saveDscr}
  , result_json = #{resultJson}
  , updt_time = #{updtTime}
WHERE imp_id = #{impId}
  AND is_deleted = 0

mapper.insert:
INSERT INTO sys_imp_tmp (
    imp_detl_id, imp_id, row_no, chk_rslt, chk_dscr, save_rslt, save_dscr
    , imp_time, opter_id, ref_id
    , fld001, fld002, fld003, fld004, fld005, fld006, fld007, fld008, fld009, fld010
    , fld011, fld012, fld013, fld014, fld015, fld016, fld017, fld018, fld019, fld020
    , fld021, fld022, fld023, fld024, fld025, fld026, fld027, fld028, fld029, fld030
    , is_deleted, crte_time, updt_time
) VALUES

    (
        #{item.impDetlId}, #{item.impId}, #{item.rowNo}, #{item.chkRslt}, #{item.chkDscr}
        , #{item.saveRslt}, #{item.saveDscr}, #{item.impTime}, #{item.opterId}, #{item.refId}
        , #{item.fld001}, #{item.fld002}, #{item.fld003}, #{item.fld004}, #{item.fld005}
        , #{item.fld006}, #{item.fld007}, #{item.fld008}, #{item.fld009}, #{item.fld010}
        , #{item.fld011}, #{item.fld012}, #{item.fld013}, #{item.fld014}, #{item.fld015}
        , #{item.fld016}, #{item.fld017}, #{item.fld018}, #{item.fld019}, #{item.fld020}
        , #{item.fld021}, #{item.fld022}, #{item.fld023}, #{item.fld024}, #{item.fld025}
        , #{item.fld026}, #{item.fld027}, #{item.fld028}, #{item.fld029}, #{item.fld030}
        , #{item.isDeleted}, #{item.crteTime}, #{item.updtTime}
    )

mapper.update:
UPDATE sys_imp_tmp
SET chk_rslt = #{chkRslt}
  , chk_dscr = #{chkDscr}
  , fld009 = #{fld009}
  , fld010 = #{fld010}
  , updt_time = #{updtTime}
WHERE id = #{id}
  AND is_deleted = 0

UPDATE sys_imp_tmp
SET save_rslt = #{saveRslt}
  , save_dscr = #{saveDscr}
  , ref_id = #{refId}
  , updt_time = #{updtTime}
WHERE id = #{id}
  AND is_deleted = 0

mapper.select:
SELECT COUNT(1)
FROM sys_imp_tmp
WHERE imp_id = #{impId}
  AND is_deleted = 0
  AND chk_rslt = #{chkRslt}

SELECT c.id ,c.parent_id ,c.pool_code ,c.pool_name ,c.pool_type ,c.pool_level ,c.market_codes ,c.variety_codes ,c.hs_pool_name ,c.in_flow_id ,c.in_flow_key ,c.in_flow_name ,c.out_flow_id ,c.out_flow_key ,c.out_flow_name ,c.simple_in_flow_id ,c.simple_in_flow_key ,c.simple_out_flow_id ,c.simple_out_flow_key ,c.batch_in_flow_id ,c.batch_in_flow_key ,c.batch_in_flow_name ,c.batch_out_flow_id ,c.batch_out_flow_key ,c.batch_out_flow_name ,c.max_capacity ,c.lock_flag ,c.open_day_adjust ,c.status ,c.is_deleted ,c.crte_time ,c.updt_time FROM ip_investment_pool c LEFT JOIN ip_investment_pool p ON p.id = c.parent_id AND p.is_deleted = 0 WHERE c.is_deleted = 0 AND c.status = 'enabled' AND c.pool_type != 'crmw' AND c.pool_name = #{childPoolName}
AND p.pool_name = #{parentPoolName}
AND NOT EXISTS ( SELECT 1 FROM ip_investment_pool child WHERE child.parent_id = c.id AND child.status = 'enabled' AND child.is_deleted = 0 ) LIMIT 1
